```yaml
name: Auto-assign Milestone
on:
  pull_request:
    types:
      - opened
      - synchronize
      - reopened
      - edited
      - closed

permissions:
  issues: write
  pull-requests: write

jobs:
  assign_milestone:
    runs-on: ubuntu-latest
    if: github.event.pull_request.merged == true
    steps:
      - name: Get current milestone
        id: get_milestone
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const pr = context.payload.pull_request;
            const targetBranch = pr.base.ref;
            let milestoneTitle = null;

            if (targetBranch === 'main') {
              milestoneTitle = '9.5';
            } else if (targetBranch.startsWith('release/')) {
              // Extract version from release/9.4 branch
              const versionMatch = targetBranch.match(/^release\/(\d+\.\d+)$/);
              if (versionMatch) {
                milestoneTitle = `${versionMatch[1]}.1`;
              }
            }

            if (milestoneTitle) {
              // Get all milestones
              const { data: milestones } = await github.rest.issues.listMilestones({
                owner: context.repo.owner,
                repo: context.repo.repo,
                state: 'open'
              });

              // Find matching milestone
              const milestone = milestones.find(m => m.title === milestoneTitle);

              if (milestone) {
                // Set milestone
                await github.rest.issues.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: pr.number,
                  milestone: milestone.number
                });

                console.log(`Assigned milestone ${milestone.title} to PR #${pr.number}`);
              } else {
                console.log(`Milestone ${milestoneTitle} not found`);
              }
            } else {
              console.log(`No milestone assigned for branch: ${targetBranch}`);
            }
